// =====================================================================
// Roteador dos lookups. Um sub-workflow atende as três tools.
// Cada consulta é parametrizada pelo escopo do gestor: uma tool nunca
// devolve dado de empresa que ele não pode ver.
// =====================================================================

const inp = $input.first().json;
const acao = String(inp.acao || '').trim();
const termo = String(inp.termo || '').trim();
const dataset = String(inp.dataset || 'afastamento').trim().toLowerCase();
const campo = String(inp.campo || '').trim().toLowerCase();

const empresas = String(inp.empresas_ids || '')
  .split(/[;,]/).map((s) => s.trim()).filter((s) => /^\d+$/.test(s));

if (!empresas.length) {
  return [{ json: { erro: 'Sem empresa autorizada; lookup bloqueado.', sql: null } }];
}
const escopo = empresas.join(', ');
const esc = (s) => String(s).replace(/'/g, "''").replace(/[\x00-\x1f\x7f]/g, '');

// Campos de domínio que podem ser listados, e de onde cada um vem.
const DOMINIOS = {
  situacao:          "SELECT DISTINCT gs.[description] AS valor FROM [ga_situation] gs INNER JOIN [user_steps] us ON us.gaSituationIdGaSituation = gs.id_ga_situation INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee WHERE us.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
  etapa:             "SELECT DISTINCT CASE s.[name] WHEN 'steps.register' THEN 'Cadastro' WHEN 'steps.scheduling' THEN 'Agendamento de perícia' WHEN 'steps.benefits' THEN 'Benefício' WHEN 'steps.renew' THEN 'Prorrogação' WHEN 'steps.exam' THEN 'Exame de retorno' WHEN 'steps.return' THEN 'Retorno ao trabalho' ELSE s.[name] END AS valor FROM [steps] s INNER JOIN [user_steps] us ON us.stepsIdSteps = s.id_steps INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee WHERE us.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
  especie_beneficio: "SELECT DISTINCT bt.benefit_type_description AS valor FROM [benefit_type] bt INNER JOIN [user_benefit] ub ON ub.benefitTypeIdBenefitType = bt.id_benefit_type INNER JOIN [user_steps] us ON ub.userStepsIdUserSteps = us.id_user_steps INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee WHERE ub.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
  status_beneficio:  "SELECT DISTINCT CASE bs.[description] WHEN 'benefit_status.deferido' THEN 'Deferido' WHEN 'benefit_status.indeferido' THEN 'Indeferido' WHEN 'benefit_status.cessado' THEN 'Cessado' ELSE bs.[description] END AS valor FROM [benefit_status] bs INNER JOIN [user_benefit] ub ON ub.benefitStatusIdBenefitStatus = bs.id_benefit_status INNER JOIN [user_steps] us ON ub.userStepsIdUserSteps = us.id_user_steps INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee WHERE ub.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
  status_atestado:   "SELECT DISTINCT CASE umi.statusMedicalIdStatusMedical WHEN 1 THEN 'Aguardando' WHEN 2 THEN 'Aprovado' WHEN 3 THEN 'Recusado' ELSE 'Outro' END AS valor FROM [user_medical_info] umi INNER JOIN [employee] e ON umi.employeeIdEmployee = e.id_Employee WHERE umi.delete_datetime IS NULL AND e.company_id IN (@ESCOPO)",
  departamento:      "SELECT DISTINCT d.[name] AS valor FROM [department] d INNER JOIN [employee] e ON e.department_id = d.id WHERE d.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
  filial:            "SELECT DISTINCT COALESCE(cf.companyName, cm.companyName) AS valor FROM [employee] e INNER JOIN [company] cm ON e.company_id = cm.id LEFT JOIN [company] cf ON e.branch_id = cf.id WHERE e.company_id IN (@ESCOPO)",
  cargo:             "SELECT DISTINCT p.position_name AS valor FROM [position] p INNER JOIN [employee] e ON e.position_id = p.id_position WHERE e.company_id IN (@ESCOPO)",
  centro_custo:      "SELECT DISTINCT cc.[name] AS valor FROM [cost_center] cc INNER JOIN [employee] e ON e.cost_center_id = cc.cost_center_id WHERE e.company_id IN (@ESCOPO)",
  motivo_afastamento: "SELECT DISTINCT CASE ar.[name] WHEN 'absenceReason.accidentAtWork' THEN 'Acidente de trabalho' WHEN 'absenceReason.commutingAccident' THEN 'Acidente de trajeto' WHEN 'absenceReason.occupationalDisease' THEN 'Doença ocupacional' WHEN 'absenceReason.ordinaryIllness' THEN 'Doença comum' WHEN 'absenceReason.domesticAccident' THEN 'Acidente doméstico' WHEN 'absenceReason.pregnancy' THEN 'Gestação / maternidade' WHEN 'absenceReason.companion' THEN 'Acompanhante' ELSE ar.[name] END AS valor FROM [absence_reason] ar INNER JOIN [user_steps] us ON us.absenceReasonIdAbsenceReason = ar.id_absence_reason INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee WHERE us.[delete] = 'N' AND e.company_id IN (@ESCOPO)",
};

let sql = null;

if (acao === 'buscar_colaborador') {
  if (termo.length < 3) {
    return [{ json: { erro: 'Termo curto: informe ao menos 3 letras do nome.', sql: null } }];
  }
  sql = `SELECT TOP 15
             e.id_Employee AS colaborador_id,
             u.[name]      AS nome,
             p.position_name AS cargo,
             COALESCE(cf.companyName, cm.companyName) AS filial,
             CASE WHEN e.active = 1 THEN 'Ativo' ELSE 'Inativo' END AS situacao_cadastro
         FROM [employee] e
         INNER JOIN [user] u ON e.user_id = u.id_user
         INNER JOIN [company] cm ON e.company_id = cm.id
         LEFT  JOIN [company] cf ON e.branch_id = cf.id
         LEFT  JOIN [position] p ON e.position_id = p.id_position
         WHERE e.[delete] = 'N'
           AND e.company_id IN (${escopo})
           AND u.[name] LIKE '%${esc(termo)}%'
         ORDER BY CASE WHEN e.active = 1 THEN 0 ELSE 1 END, u.[name]`;
}

else if (acao === 'buscar_cid') {
  if (termo.length < 3) {
    return [{ json: { erro: 'Termo curto: informe ao menos 3 letras da doença ou o código.', sql: null } }];
  }
  sql = `SELECT TOP 15
             c.code_cid    AS cid_codigo,
             c.[description] AS cid_descricao
         FROM [cid] c
         WHERE c.[description] LIKE '%${esc(termo)}%'
            OR c.code_cid LIKE '${esc(termo)}%'
         ORDER BY CASE WHEN c.code_cid LIKE '${esc(termo)}%' THEN 0 ELSE 1 END, c.code_cid`;
}

else if (acao === 'listar_valores') {
  const base = DOMINIOS[campo];
  if (!base) {
    return [{ json: {
      erro: `Campo "${campo}" não é listável.`,
      campos_listaveis: Object.keys(DOMINIOS), sql: null } }];
  }
  sql = base.replace('@ESCOPO', escopo);
  sql = sql.replace(/^SELECT DISTINCT/, 'SELECT DISTINCT TOP 60');
  sql += ' ORDER BY valor';
}

else {
  return [{ json: { erro: `Ação "${acao}" desconhecida.`,
                    acoes: ['buscar_colaborador', 'buscar_cid', 'listar_valores'], sql: null } }];
}

return [{ json: { acao, sql } }];

// Devolve para a tool um texto curto e literal. Nada de prosa: o agente
// precisa dos VALORES para colocar no spec.
const roteador = $('Roteador do lookup').first().json;

if (roteador.erro) {
  return [{ json: { resposta: 'ERRO: ' + roteador.erro +
    (roteador.campos_listaveis ? ' Campos listáveis: ' + roteador.campos_listaveis.join(', ') : '') } }];
}

const linhas = $input.all().map((i) => i.json).filter((j) => j && Object.keys(j).length);

if (!linhas.length) {
  return [{ json: { resposta: 'Nenhum resultado. Não invente valor: peça ao gestor para especificar melhor.' } }];
}

const texto = linhas.map((l) => Object.entries(l)
  .map(([k, v]) => `${k}=${v === null ? '-' : v}`).join(' | ')).join('\n');

return [{ json: { resposta: `${linhas.length} resultado(s):\n${texto}` } }];

